<script setup>import{useForm,router}from'@inertiajs/vue3';import AdminLayout from'../../../Layouts/AdminLayout.vue';const props=defineProps({reels:Array,products:Array,services:Array}),form=useForm({item_type:'product',item_id:'',title:'',caption:'',media_type:'image',media_file:null,external_url:'',cover_image_file:null,cta_label:'',display_seconds:6,is_active:true,sort_order:0});const items=()=>form.item_type==='product'?props.products:props.services;const submit=()=>form.post('/admin/reels',{forceFormData:true,onSuccess:()=>form.reset()});</script><template><AdminLayout><p class="section-kicker">Homepage</p><h1 class="section-title">Product reels</h1><div class="mt-6 grid gap-5 lg:grid-cols-[380px_1fr]"><form class="card h-fit p-5" @submit.prevent="submit"><h2 class="font-black">Add reel</h2><div class="mt-4 grid gap-3"><select v-model="form.item_type" class="input"><option value="product">Product</option><option value="service">Service</option></select><select v-model="form.item_id" class="input"><option value="">Select item</option><option v-for="i in items()" :key="i.id" :value="i.id">{{i.name}}</option></select><input v-model="form.title" class="input" placeholder="Title"><textarea v-model="form.caption" class="input" placeholder="Caption"></textarea><select v-model="form.media_type" class="input"><option value="image">Image</option><option value="video">Video</option></select><input type="file" @change="form.media_file=$event.target.files[0]"><input v-model="form.external_url" class="input" placeholder="Or external video URL"><button class="btn-primary">Add reel</button></div></form><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="r in reels" :key="r.id" class="card overflow-hidden"><img :src="r.cover_url" class="aspect-[9/14] w-full object-cover"><div class="p-3"><b>{{r.title||r.product?.name||r.service?.name}}</b><button class="mt-2 block text-sm font-bold text-red-600" @click="router.delete(`/admin/reels/${r.id}`)">Move to Trash</button></div></div></div></div></AdminLayout></template>
